"""Формує docs/gds_report.md з docs/evidence/gds.json."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
o = json.loads((ROOT / "docs/evidence/gds.json").read_text(encoding="utf-8"))
b = o["bench"]; pr = o["pagerank"]; lv = o["louvain"]


def ops(p): return "\n".join("  " * d + f"{n} {a}".strip() + f"   [записів: {r}, {t} мс]" for d, n, a, r, t in p["ops"])


L = ["# Результат 4. Аналіз графа та продуктивність", "",
     "**Рушій і заміна GDS.** Neo4j GDS тут недоступний. PageRank виконано нативною процедурою FalkorDB `CALL algo.pageRank(null, null)` (весь граф: 370 вузлів, 757 зв'язків); Louvain у FalkorDB немає, тому спільноти обчислено `networkx.louvain_communities` (seed 42, resolution 1.0) на вигрузці графа без напрямку. Це не Neo4j GDS: назви процедур, параметри проєкції і числа можуть відрізнятися. Скрипт: `scripts/gds.py`; сирі результати: `docs/evidence/gds.json`.", "",
     "## 1. PageRank: топ-10", "", "| № | Вузол | Оцінка (FalkorDB) | Топ networkx |", "|---|---|---|---|"]
L += [f"| {i+1} | {a} | {s} | {pr['networkx_top10'][i][0]} ({pr['networkx_top10'][i][1]}) |" for i, (a, s) in enumerate(pr["top10"])]
L += ["", f"Перевірка: незалежний `networkx.pagerank` (alpha 0.85) на тому самому графі дає той самий склад топ-10 (перетин {pr['overlap_top10']}/10); сума оцінок нативного PageRank = {pr['sum']}. Порядок окремих позицій може відрізнятися через різну обробку вузлів без вихідних зв'язків.", "",
      "PageRank серед осіб (`MATCH (p:Person) RETURN p.name, p.pagerank`): " + "; ".join(f"{n} — {s:.4f}" for n, s, c in o["person_pagerank"]) + ".", "",
      f"## 2. Louvain: {lv['n']} спільнот, модулярність {lv['modularity']}", "", "| Спільнота | Вузлів | Склад за мітками | Ключові вузли |", "|---|---|---|---|"]
for c in lv["communities"][:9]: L.append(f"| {c['id']} | {c['size']} | {', '.join(f'{k} {v}' for k, v in c['labels'].items())} | {', '.join(c['key_nodes'][:5]) or '—'} |")
L += [f"| 9–15 | по 5 | Variant 1 + Annotation 4 | (окремі «зірки» варіантів) |", "| 16 | 3 | Concept 2, Situation 1 | DataArtifact, GenePanel |", "",
      "## 3. Інтерпретація для предметної області", "",
      "1. Найвищий PageRank мають чотири вузли `AnnotationType` (FS, QD, SOR, MQ — по ≈ 0.08), тобто саме типи анотацій є головними вузлами збору знань: на кожен із них вказує понад шістдесят вузлів-анотацій, і всі правила жорсткої фільтрації (`Threshold`) підключаються через них. Для змісту це означає: зміна визначення або порога для цих показників зачіпає найбільшу частину графа — це підтверджує й запит аналізу впливу c09.",
      "2. Далі йдуть вузли класів `GeneticVariant`, `Person`, `Relative`, `SNP`: ієрархія класів працює як «шини», через які сходяться всі екземпляри; це корисно для запитів із замиканням `SUBCLASS_OF*`, але є артефактом моделі (кожен варіант прив'язаний до класу), а не біологічною важливістю.",
      "3. Серед генів найвищий PageRank у BRCA2 (0.0053): у цьому наборі він має найбільше варіантів (20). Це відображає розмір вибірки в синтетичній когорті, а не клінічну значущість гена; на реальних даних такий висновок був би хибним без нормування.",
      "4. Louvain розбив граф на 17 спільнот; сім найбільших (32–49 вузлів) сформовані навколо хабів — типів анотацій (SOR, MQ, QD), генів (PALB2, TP53, BRCA2, BRCA1), зразків і класів; інакше кажучи, алгоритм здебільшого відтворює «зірки» навколо хабів, а не нові біологічні групи. Модулярність 0.43 помірна.",
      "5. Єдина спільнота з явним доменним змістом — №7 (26 вузлів): усі 8 осіб родини, 2 діагнози, процедура CT-01, ступені споріднення й класи `Relative`/`Proband`. Вона показує, що родинний підграф — окрема когерентна частина бази знань, слабко пов'язана з підграфом якості варіантів (єдиний місток — варіант VAR-001, який носить пробанд). Це пряма підстава зберігати їх як різні модулі й обмінюватись між ними лише через `CARRIES`.",
      "6. Спільнота №8 (21 вузол) об'єднує процедуру HF-01, файли sample1.vcf/.bam, прилад і чотири пороги (FS, MQRankSum, ReadPosRankSum) — «ланцюг походження даних і правил», що узгоджується з аналізом впливу c10.",
      "7. Обмеження: граф малий і синтетичний, тому структура спільнот значною мірою визначається схемою даних (кожна анотація належить рівно одному варіанту та одному типу); Louvain недетермінований без seed, тут seed = 42. Висновки про «значущість» вузлів слід вважати ілюстрацією методу, а не знанням про біологію.", "",
      "## 4. Збереження результатів у графі", "",
      f"`SET n.pagerank, n.community` виконано для всіх вузлів: з `pagerank` — {o['saved']['nodes_with_pagerank']}, зі `community` — {o['saved']['nodes_with_community']}. Перевірка `MATCH (n) RETURN n.community, count(n) ORDER BY count(n) DESC LIMIT 5`: " + ", ".join(f"спільнота {c} — {s}" for c, s in o["saved"]["check"]) + ".", "",
      "## 5. PROFILE", "", "### Запит 1 — c01 (SNP із QD < 2) на графі dkh", "", "```", ops(o["profile_real"]["c01"]), "```", f"Час: {o['profile_real']['c01']['ms_median']} мс.", "",
      "### Запит 2 — c09 (аналіз впливу порога QD, 5 кроків) на графі dkh", "", "```", ops(o["profile_real"]["c09"]), "```", f"Час: {o['profile_real']['c09']['ms_median']} мс.", "",
      "На малому графі (370 вузлів) обидва запити виконуються за частки мілісекунди й оптимізувати нічого, тому оптимізацію показано на синтетичному графі.", "",
      f"## 6. Оптимізація (синтетичний граф: {b['variants']} варіантів, {b['nodes']} вузлів, {b['rels']} зв'язків)", "",
      "Запит: кількість SNP-варіантів із QD < 2 (відповідь однакова в усіх варіантах: " + str(b["answer"]) + "; збіг перевірено: " + str(b["answers_equal"]) + "). Значення в синтетичних анотаціях детерміновані (формула від номера варіанта), випадковості немає.", "",
      "```cypher", "// до (Q_BEFORE)", "MATCH (v:Variant)-[:HAS_ANNOTATION]->(a:Annotation)", "WHERE v.type = 'SNP' AND a.name = 'QD' AND a.value < 2.0", "RETURN count(v)", "```", "",
      "PROFILE до оптимізації (без індексу):", "", "```", ops(b["before"]), "```", "",
      "Крок 1 — переписування шаблону (початок з `Annotation {name:'QD'}`): без індексу план практично той самий (оптимізатор уже починає зі сканування `Annotation`), час не покращився.", "", "```", ops(b["rewrite"]), "```", "",
      "Крок 2 — індекс: `bg.create_node_range_index('Annotation', 'name', 'value')` (у Neo4j — `CREATE INDEX FOR (a:Annotation) ON (a.name, a.value)`).", "", "PROFILE після (запит Q_BEFORE з індексом):", "", "```", ops(b["before_index"]), "```", "",
      "| Варіант | Медіана 5 запусків, мс | Сканування Annotation |", "|---|---|---|",
      f"| до (без індексу) | {b['before']['ms_median']} | Node By Label Scan — 80 000 записів |", f"| переписування, без індексу | {b['rewrite']['ms_median']} | Node By Label Scan — 80 000 |",
      f"| після (індекс) | {b['before_index']['ms_median']} | Node By Index Scan — {[r for r in b['before_index']['ops'] if 'Index' in r[1]][0][3]} записів |", f"| переписування + індекс | {b['rewrite_index']['ms_median']} | Node By Index Scan — {[r for r in b['rewrite_index']['ops'] if 'Index' in r[1]][0][3]} |", "",
      f"Висновок: індекс замінив сканування 80 000 вузлів на вибірку 1145, час впав з {b['before']['ms_median']} до {b['before_index']['ms_median']} мс (≈ {round(b['before']['ms_median']/b['before_index']['ms_median'],1)}×); саме по собі переписування запиту нічого не дало. Вимірювання на одному рушії та одній машині; різниця переписування vs. база (15 vs 19 мс) — у межах шуму.", ""]
(ROOT / "docs/gds_report.md").write_text("\n".join(L), encoding="utf-8"); print("ok")
